.ct-name { margin-top: .7rem; font: 600 .7rem var(--mono); letter-spacing: .08em; text-transform: uppercase;
           color: var(--paper); opacity: .6; text-align: center; }
.ct-say { margin-top: .2rem; font: 700 .82rem var(--mono); color: var(--paper); text-align: center; }
.ct-say .ct-o { color: var(--ct-cen); }
.ct-say .ct-e { color: var(--ct-edge); }
@media (prefers-reduced-motion: reduce) {
  .ct-a, .ct-b, .ct-w, .ct-x { animation: none; }
}

.an-area { --ar-top: var(--gold); --ar-bot: #6fd8c4; }
.an-area .ar-svg { display: block; width: min(72vw, 17rem); max-width: 100%; height: auto; margin: 0 auto; }
.ar-top { --ar: var(--ar-top); } .ar-bot { --ar: var(--ar-bot); } .ar-r { --ar: var(--paper); }
.ar-ring { fill: none; stroke: var(--paper); stroke-opacity: .22; stroke-width: .4; }
.ar-slot { fill: var(--ar); fill-opacity: .07; stroke: var(--ar); stroke-opacity: .25; stroke-width: .3; }
.ar-sl { fill: var(--ar); fill-opacity: .9; stroke: var(--bg); stroke-width: .5; stroke-linejoin: round;
         transform-box: view-box; transform-origin: 0 0; transform: var(--to);
         animation: ar-fly 6.4s cubic-bezier(.55, 0, .3, 1) infinite; animation-delay: var(--d); }
@keyframes ar-fly {
  0%        { transform: var(--from); }
  14.06%, 57.81% { transform: var(--to); }
  71.87%, 100% { transform: var(--from); }
}
.ar-dim { fill: none; stroke: var(--ar); stroke-width: .5; stroke-linecap: round; }
.ar-lab { fill: var(--ar); font: 700 5.6px var(--mono); text-anchor: middle; dominant-baseline: central; }
.ar-dim, .ar-lab { animation: ar-lab 6.4s ease-out infinite; }
@keyframes ar-lab { 0%, 26.56% { opacity: 0; } 31.25%, 59.38% { opacity: 1; }
                    64.06%, 100% { opacity: 0; } }
.ar-say { margin-top: .6rem; font: 700 .95rem var(--mono); color: var(--paper); text-align: center; }
.ar-say b { color: var(--ar); }
@media (prefers-reduced-motion: reduce) {
  .ar-sl, .ar-dim, .ar-lab { animation: none; }
}

.an-pyth { --py-a: #6fd8c4; --py-b: #6fa8dc; --py-c: var(--gold);
               width: min(74vw, 18rem, 100%); text-align: center; }
.py-svg { display: block; width: 100%; height: auto; }
.py-a { --py: var(--py-a); } .py-b { --py: var(--py-b); } .py-c { --py: var(--py-c); }
.py-edge { fill: none; stroke: var(--py); stroke-width: .1; stroke-linejoin: round; }
.py-grid { fill: none; stroke: var(--py); stroke-opacity: .3; stroke-width: .04; }
.py-tri { fill: none; stroke: var(--paper); stroke-width: .16; stroke-linejoin: round; }
.py-right { fill: none; stroke: var(--paper); stroke-opacity: .55; stroke-width: .08; }
.py-cell { fill: var(--py); fill-opacity: .78; stroke: var(--bg); stroke-width: .08;
           transform-box: view-box; transform-origin: 0 0; transform: var(--to);
           animation: py-fly 7.6s cubic-bezier(.55, 0, .3, 1) infinite; animation-delay: var(--d); }
@keyframes py-fly {
  0%        { transform: var(--from); }
  9.87%, 57.24% { transform: var(--to); }
  67.11%, 100% { transform: var(--from); }
}
.py-n { font: 700 1.3px var(--mono); text-anchor: middle; dominant-baseline: central; fill: var(--py);
        stroke: var(--bg); stroke-width: .24px; paint-order: stroke; stroke-linejoin: round; }
.py-nc, .py-sum { animation: py-sum 7.6s ease-out infinite; }
@keyframes py-sum { 0%, 35.53% { opacity: 0; } 38.82%, 59.21% { opacity: 1; }
                    62.5%, 100% { opacity: 0; } }
.py-say { margin-top: .6rem; font: 700 .95rem var(--mono); letter-spacing: .06em;
          color: color-mix(in srgb, var(--paper) 80%, transparent); }
.py-say b { color: var(--py); }
@media (prefers-reduced-motion: reduce) {
  .py-cell, .py-nc, .py-sum { animation: none; }
}

.tk-row { display: flex; justify-content: center; gap: .45rem; }
.tk-deg i { width: 2.4rem; text-align: center; color: #8b8b80;
            font: 700 .72rem var(--mono); font-style: normal; }
.tk-val { margin-top: .35rem; }
.tk-val i { width: 2.4rem; display: grid; place-items: center; font-style: normal; opacity: 0;
            animation: tk-in .5s ease-out both; animation-delay: calc(.5s + var(--i) * .42s); }
.tk-val b { display: block; padding: 0 .25rem; border-bottom: 1.5px solid var(--paper);
            color: var(--paper); font: 700 .84rem var(--mono); }
.tk-val u { display: block; text-decoration: none; color: var(--paper); font: 700 .84rem var(--mono); }
@keyframes tk-in { from { opacity: 0; transform: translateY(.4rem); } to { opacity: 1; } }
.tk-say { margin-top: .9rem; font: 700 .9rem var(--mono); color: var(--paper); text-align: center; }
.tk-say b { color: #e8862c; }
@media (prefers-reduced-motion: reduce) {
  .tk-val i { animation: none; opacity: 1; }
}

