.an-bin { display: grid; place-items: center; }
.an-bin .bn-row { display: flex; gap: .42rem; }
.bn-row i { width: 1.7rem; height: 2.4rem; border-radius: 5px; background: #241f18;
            border: 2px solid #4a3f2c; font-style: normal;
            animation: bn-count 1.44s steps(1, end) infinite; }
.bn-row i:nth-child(8) { animation-duration: .12s; }
.bn-row i:nth-child(7) { animation-duration: .24s; }
.bn-row i:nth-child(6) { animation-duration: .48s; }
.bn-row i:nth-child(5) { animation-duration: .96s; }
.bn-row i:nth-child(4) { animation-duration: 1.92s; }
.bn-row i:nth-child(3) { animation-duration: 3.84s; }
.bn-row i:nth-child(2) { animation-duration: 7.68s; }
.bn-row i:nth-child(1) { animation-duration: 15.36s; }
@keyframes bn-count {
  0%, 49.9%   { background: #241f18; border-color: #4a3f2c; box-shadow: none; }
  50%, 100%   { background: #f0b45f; border-color: #ffd48a;
                box-shadow: 0 0 12px rgb(240 180 95 / .55); }
}
.bn-say { margin-top: .8rem; font: 600 .7rem var(--mono); letter-spacing: .1em;
          color: rgb(240 236 224 / .5); text-align: center; }
@media (prefers-reduced-motion: reduce) {
  .bn-row i { animation: none; opacity: 1; transform: none; }
  .bn-row i:nth-child(2n) { background: #f0b45f; border-color: #ffd48a; }
}

.an-sort { display: grid; place-items: center; }
.an-sort .so-row { display: flex; align-items: flex-end; gap: .3rem; height: 6rem; }
.so-row i { width: 1.5rem; height: 100%; transform-origin: bottom;
            transform: scaleY(var(--h));
            border-radius: 3px 3px 0 0; background: #6fa8dc;
            animation: so-swap 3.2s cubic-bezier(.5,0,.5,1) infinite;
            animation-delay: calc(var(--i) * .09s); }
@keyframes so-swap {
  0%, 6%    { transform: scaleY(var(--h)); background: #6fa8dc; }
  44%, 60%  { transform: scaleY(calc(.12 + var(--i) * .11)); background: #6fd8a0; }
  98%, 100% { transform: scaleY(var(--h)); background: #6fa8dc; }
}
.so-say { margin-top: .8rem; font: 600 .76rem var(--mono); letter-spacing: .14em;
          color: rgb(240 236 224 / .5); text-align: center; }
@media (prefers-reduced-motion: reduce) {
  .so-row i { animation: none; opacity: 1; transform: scaleY(calc(.12 + var(--i) * .11)); background: #6fd8a0; }
}

.an-fit { --fit-u: #6fa8dc; }
.fit-svg { display: block; width: min(88vw, 21rem); max-width: 100%; height: auto; }
.fit-svg text { font: 700 13px var(--mono); text-anchor: middle; fill: var(--paper); }
.fit-bar { fill: var(--paper); fill-opacity: .1; stroke: var(--paper); stroke-opacity: .6; stroke-width: 1; }
.fit-tk { stroke: var(--paper); stroke-opacity: .4; stroke-width: 1; }
.fit-svg .fit-lab text { font-size: 11px; font-weight: 600; fill-opacity: .75; }
.fit-svg .fit-lab .fit-end { font-weight: 700; fill-opacity: 1; }
.fit-lf { color: color-mix(in srgb, var(--paper) 75%, transparent); }
.fit-wall { stroke: var(--paper); stroke-opacity: .75; stroke-width: 1.2; stroke-dasharray: 2.5 2; }
.fit-ok { stroke: var(--gold); stroke-width: 2; }
.fit-b { fill: var(--fit-u); }
.fit-no { fill: var(--coral); }
.fit-dv { stroke: var(--bg); stroke-opacity: .55; stroke-width: 1.1; }
.fit-svg .fit-bn { fill: var(--bg); }
.fit-svg .fit-bf text { font-size: 10.8px; fill: var(--bg); }
.fit-bf { color: var(--bg); }
.fit-gh { fill: none; stroke: var(--fit-u); stroke-opacity: .9; stroke-width: 1.2; stroke-dasharray: 3 2; }
.fit-svg .fit-n, .fit-svg .fit-n text { fill: var(--gold); }
.fit-svg .fit-n text, .fit-svg .fit-tf { font-size: 11px; }
.fit-svg .fit-tf { fill: var(--coral); }
.fit-fl { stroke: currentColor; stroke-width: 1.2; }
.fit-n { color: var(--gold); }
.fit-svg .fit-say { font-size: 11.5px; }
.fit-svg .fit-sum text { font-size: 17px; }
.fit-svg .fit-sum g text { font-size: 11.5px; }
.fit-svg .fit-g, .fit-svg .fit-g text { fill: var(--gold); }
.fit-svg .fit-u, .fit-svg .fit-u text { fill: var(--fit-u); }
.fit-svg .fit-o { fill-opacity: .55; }
.fit-g { color: var(--gold); }
.fit-u { color: var(--fit-u); }
.fit-pp { transform-box: fill-box; transform-origin: center; }
.fit-s ~ .fit-s, .fit-ot { opacity: 0; }
